from lib import *
from fractions import Fraction as Fr
import math
tablefig('aq15_sq',['n','n²','n³','n','n²','n³'],[[str(i),str(i*i),str(i**3),str(i+13),str((i+13)**2),str((i+13)**3)] for i in range(1,14)],[1,1.3,1.6,1,1.3,1.6],title='Squares and cubes you should know')
def html():
    h=top('Calculation Tricks, Mini Test and Formula Sheet','ADVANCED QUANT · TRICKS AND REVISION','#0f766e')
    h+=intro('Speed decides the score. This chapter gives you the mental-maths tricks that save 20–30 seconds per question, a one-page formula sheet for last-day revision, and a timed mini test to check where you stand.')
    h+=fig('aq15_sq','Memorise these. They appear inside almost every question.')
    h+=form('Speed tricks',['<b>Square ending in 5:</b> (n5)² = n(n+1) followed by 25. Example 75² = 7×8 | 25 = 5625.','<b>Multiply by 11:</b> add neighbouring digits. 35 × 11 = 3 | 8 | 5 = 385.','<b>Square near 100/50:</b> 98² = (100 − 2)² = 9604; 52² = (50+2)² = 2704.','<b>(a+b)(a−b) = a² − b²:</b> 47 × 53 = 50² − 3² = 2491.','<b>Percent ↔ fraction:</b> 12.5 = 1/8, 16.67 = 1/6, 14.28 = 1/7, 11.11 = 1/9, 6.25 = 1/16.','<b>Multiply by 5:</b> halve and ×10. 48 × 5 = 240. <b>By 25:</b> ÷4 ×100. <b>By 125:</b> ÷8 ×1000.','<b>Divisibility:</b> 3 and 9 by digit sum, 4 by last two digits, 8 by last three, 11 by alternating sum, 7 by splitting 1001.','<b>Approximation:</b> round numbers to 2 digits, compare options, and refine only if two options are close.','<b>Option elimination:</b> use the last digit or the sign of the answer to remove options before calculating.'])
    h+=ex('Compute 75² and 85².',f'{75**2}; {85**2}','n(n+1) | 25: 7×8 = 56 → 5625; 8×9 = 72 → 7225.')
    h+=ex('Compute 47 × 53 without a calculator.',str(47*53),'(50 − 3)(50 + 3) = 2500 − 9 = 2491.')
    h+=ex('Find 17.5% of 480 quickly.',str(Fr(175,1000)*480),'10% = 48, 5% = 24, 2.5% = 12. Sum = 84.')
    h+=ex('Estimate 4999 × 21 using the nearest round number.',str(4999*21),'5000 × 21 = 105000 minus 21 = 104979.')
    h+=h3('One-page formula sheet')
    h+=tb(['Topic','Must-know formulas'],[['Number theory','Number of factors = ∏(e+1); zeros in n! = ⌊n/5⌋+⌊n/25⌋+…; HCF × LCM = product of two numbers.'],['Remainders','Cyclicity of last digit (4 for 2,3,7,8); Fermat; CRT; digital root mod 9.'],['Algebra','Sum of roots = −b/a; product = c/a; AM ≥ GM; discriminant b² − 4ac.'],['Series/logs','AP: n/2(2a+(n−1)d); GP: a(rⁿ−1)/(r−1); log(ab) = log a + log b.'],['P&C','nPr = n!/(n−r)!; nCr = n!/(r!(n−r)!); circular (n−1)!; derangement Dₙ.'],['Probability','P(A∪B) = P(A) + P(B) − P(A∩B); P(A|B) = P(A∩B)/P(B); Bayes.'],['Sets','Inclusion–exclusion with 3 sets; exactly-two = pairs − 3·triple.'],['DI','% change = (new−old)/old; CAGR = (end/start)^(1/n) − 1.'],['Work','Total = LCM; rate = total/days; pipes: inlet +, outlet −.'],['TSD','Avg speed = 2ab/(a+b); relative speed; boats u±v; × 5/18.'],['Percent/P&L','Successive: a + b + ab/100; equal SP gain/loss ⇒ loss x²/100.'],['Interest','CI = P(1+r/100)ⁿ − P; CI − SI (2 yr) = P(r/100)².'],['Mensuration','Triangle ½bh; circle πr²; cylinder πr²h; cone ⅓πr²h; sphere 4/3πr³.']],'sm')
    # mini test
    h+=h3('Timed mini test: 12 questions, 20 minutes')
    qs=[('Number of factors of 360?',str(360 and sum(1 for i in range(1,361) if 360%i==0)),'B'),('Trailing zeros in 100!?',str(100//5+100//25),'B'),('Remainder when 2^100 is divided by 7?',str(pow(2,100,7)),'M'),('Sum of the first 20 terms of 3, 7, 11, …?',str(sum(3+4*i for i in range(20))),'M'),('Number of ways to arrange the letters of LEVEL?',str(math.factorial(5)//(math.factorial(2)*math.factorial(2))),'M'),('Probability of two heads in three tosses?',str(Fr(3,8)),'M'),('A job takes A 12 days and B 20 days. Together?',str(Fr(12*20,32)),'M'),('Average speed for 60 km/h up and 40 km/h down?',str(Fr(2*60*40,100)),'M'),('CI on ₹5,000 at 10% for 2 years?',str(5000*Fr(121,100)-5000),'M'),('Marked 30% above cost, 10% discount: profit %?',str(Fr(130*90,100)-100),'M'),('Mix ₹30/kg and ₹50/kg to get ₹42/kg: ratio?','2 : 3','A'),('Volume of a cone of radius 7 and height 6 (π = 22/7)?',str(Fr(1,3)*Fr(22,7)*49*6),'A')]
    h+=pq('15. Tricks, Mini Test and Formula Sheet','Mini test (set a 20-minute timer)',qs)
    h+=tips(['Do the questions you know first; leave the long ones for the end.','Score yourself: 10+ is excellent, 7–9 is good, below 7 revisit the weak topic chapters.'])
    return h+end()
